create type public.outbox_event_status as enum ('PENDING','PROCESSING','PROCESSED','FAILED');
create table public.organization_feature_flags(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,flag_key text not null check(flag_key ~ '^[a-z][a-z0-9_]{2,79}$'),enabled boolean not null default false,updated_by uuid references public.user_profiles(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,flag_key)
);
create table public.outbox_events(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,event_type text not null check(event_type ~ '^[A-Z][A-Z0-9_]{2,119}$'),aggregate_type text not null check(aggregate_type ~ '^[A-Z][A-Z_]{1,79}$'),aggregate_id uuid,payload jsonb not null default '{}'::jsonb,idempotency_key text not null check(length(trim(idempotency_key)) between 8 and 200),status public.outbox_event_status not null default 'PENDING',attempts integer not null default 0 check(attempts>=0),available_at timestamptz not null default now(),last_error text,correlation_id uuid not null default gen_random_uuid(),created_at timestamptz not null default now(),processed_at timestamptz,unique(organization_id,idempotency_key)
);
create table public.outbox_event_attempts(
 id uuid primary key default gen_random_uuid(),outbox_event_id uuid not null references public.outbox_events(id) on delete restrict,attempt_number integer not null check(attempt_number>0),outcome text not null check(outcome in ('STARTED','SUCCEEDED','FAILED')),error_summary text,created_at timestamptz not null default now(),unique(outbox_event_id,attempt_number,outcome)
);
create index outbox_events_dispatch_idx on public.outbox_events(status,available_at,created_at); create trigger organization_feature_flags_updated before update on public.organization_feature_flags for each row execute function public.set_updated_at();
alter table public.organization_feature_flags enable row level security; alter table public.outbox_events enable row level security; alter table public.outbox_event_attempts enable row level security;
create policy "admins read feature flags" on public.organization_feature_flags for select to authenticated using(public.has_organization_role(organization_id,array['SUPER_ADMIN','ORG_ADMIN']::public.platform_role[]));
create policy "auditors read outbox events" on public.outbox_events for select to authenticated using(public.has_organization_role(organization_id,array['SUPER_ADMIN','ORG_ADMIN','AUDITOR']::public.platform_role[]));
create policy "auditors read outbox attempts" on public.outbox_event_attempts for select to authenticated using(exists(select 1 from public.outbox_events e where e.id=outbox_event_id and public.has_organization_role(e.organization_id,array['SUPER_ADMIN','ORG_ADMIN','AUDITOR']::public.platform_role[])));
create or replace function public.is_feature_enabled(target_organization_id uuid,target_flag_key text) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.organization_feature_flags where organization_id=target_organization_id and flag_key=target_flag_key and enabled); $$;
create or replace function public.enqueue_outbox_event(target_organization_id uuid,target_event_type text,target_aggregate_type text,target_aggregate_id uuid,target_payload jsonb,target_idempotency_key text)
returns uuid language plpgsql security definer set search_path=public as $$ declare event_id uuid;
begin if not public.has_organization_role(target_organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER','DISPATCHER']::public.platform_role[]) then raise exception 'OUTBOX_NOT_AUTHORIZED'; end if; if coalesce(length(trim(target_idempotency_key)),0) not between 8 and 200 then raise exception 'OUTBOX_INVALID_IDEMPOTENCY_KEY'; end if;
insert into public.outbox_events(organization_id,event_type,aggregate_type,aggregate_id,payload,idempotency_key) values(target_organization_id,target_event_type,target_aggregate_type,target_aggregate_id,coalesce(target_payload,'{}'::jsonb),trim(target_idempotency_key)) on conflict(organization_id,idempotency_key) do update set idempotency_key=excluded.idempotency_key returning id into event_id;
insert into public.audit_logs(organization_id,actor_id,action,entity_type,entity_id,after_value,source) values(target_organization_id,auth.uid(),'OUTBOX_EVENT_ENQUEUED','outbox_event',event_id,jsonb_build_object('event_type',target_event_type,'aggregate_type',target_aggregate_type),'WEB'); return event_id; end; $$;
revoke all on function public.is_feature_enabled(uuid,text),public.enqueue_outbox_event(uuid,text,text,uuid,jsonb,text) from public; grant execute on function public.is_feature_enabled(uuid,text),public.enqueue_outbox_event(uuid,text,text,uuid,jsonb,text) to authenticated;
